      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'string',
        },
      },
    },
    value: {
      control: { type: 'number' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'number',
        },
      },
    },
    text: {
      control: { type: 'text' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'string',
        },
      },
    },
    template: {
      control: 'select',
      options: ['visible', 'hidden', 'unavailable'],
      defaultValue: { summary: 'visible' },
      table: {
        type: {
          summary: 'visible | hidden | unavailable',
        },
